package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 线路图有向区段请求项，行驶分钟为正整数。
 */
public record LineSegmentRequest(
        @NotBlank String sectionId,
        @NotBlank String fromStation,
        @NotBlank String toStation,
        @NotNull @Min(1) Integer travelMinutes) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.List;

/**
 * 线路图整体替换请求。requestId 为幂等键；expectedVersion 必须等于当前图版本，
 * 成功一次图版本加一；区段 1～20 条、涉及站点不超过 10 个。
 */
public record ReplaceGraphRequest(
        @NotBlank String requestId,
        @NotBlank String operator,
        @NotNull Integer expectedVersion,
        @NotNull @Size(min = 1, max = 20) List<@Valid LineSegmentRequest> segments) {
}

package com.example.starter.plan.web.dto;

import java.util.List;

/**
 * 线路图响应：当前版本与区段清单。
 */
public record GraphResponse(int version, List<LineSegmentRequest> segments) {
}

package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.Instant;

/**
 * 寻径发布请求：按图版本寻径并一次发布整张日计划。
 * requestId 为幂等键；departUtc 必须为 UTC 整分钟；latestArrivalUtc 为最晚到达（含）。
 */
public record RoutePublishRequest(
        @NotBlank String requestId,
        @NotBlank String operator,
        @NotBlank String scheduleKey,
        @NotNull Integer graphVersion,
        @NotBlank String trainNo,
        @NotBlank String fromStation,
        @NotBlank String toStation,
        @NotNull Instant departUtc,
        @NotNull Instant latestArrivalUtc) {
}

