235	            return replayIfPresent(OP_ROUTE_PUBLISH, req.requestId(), hash,
236	                    RoutePublishResponse.class)
237	                    .orElseThrow(() -> conflict("SCHEDULE_KEY_EXISTS",
238	                            "scheduleKey 已存在: " + req.scheduleKey()));
239	        }
240	    }
241	
242	    /**
243	     * 寻径请求参数级校验：出发必须 UTC 整分钟，最晚到达必须晚于出发，起终站不得相同。
244	     */
245	    private void validateRouteParams(RoutePublishRequest req) {
246	        if (req.departUtc().getEpochSecond() % 60 != 0) {
247	            throw badRequest("出发时刻必须为 UTC 整分钟: " + req.departUtc());
248	        }
249	        if (!req.latestArrivalUtc().isAfter(req.departUtc())) {
250	            throw badRequest("最晚到达必须晚于出发时刻");
251	        }
252	        if (req.fromStation().equals(req.toStation())) {
253	            throw badRequest("起终站不得相同: " + req.fromStation());
254	        }
255	    }
256	
257	    /**
258	     * 候选路径：不重复站点的有向简单路径及总分钟。
259	     */
260	    private record Path(List<LineSegment> segments, int totalMinutes) {
261	    }
262	
263	    /**
264	     * 枚举全部简单路径，按（总分钟升序，区段编号序列字典序）排序。
265	     */
266	    private List<Path> enumeratePaths(List<LineSegment> segments, String from, String to) {
267	        Map<String, List<LineSegment>> adjacency = new LinkedHashMap<>();
268	        for (LineSegment s : segments) {
269	            adjacency.computeIfAbsent(s.fromStation(), k -> new ArrayList<>()).add(s);
270	        }
271	        List<Path> paths = new ArrayList<>();
272	        Set<String> visited = new HashSet<>();
273	        visited.add(from);
274	        dfs(adjacency, from, to, visited, new ArrayList<>(), 0, paths);
275	        paths.sort(Comparator.comparingInt(Path::totalMinutes)
276	                .thenComparing(path -> path.segments().stream().map(LineSegment::sectionId).toList(),
277	                        (a, b) -> {
278	                            int n = Math.min(a.size(), b.size());
279	                            for (int i = 0; i < n; i++) {
280	                                int c = a.get(i).compareTo(b.get(i));
281	                                if (c != 0) {
282	                                    return c;
283	                                }
284	                            }
285	                            return Integer.compare(a.size(), b.size());
286	                        }));
287	        return paths;
288	    }
289	
290	    private void dfs(Map<String, List<LineSegment>> adjacency, String current, String target,
291	                     Set<String> visited, List<LineSegment> stack, int minutes, List<Path> out) {
292	        if (current.equals(target)) {
293	            out.add(new Path(List.copyOf(stack), minutes));
294	            return;
295	        }
296	        for (LineSegment next : adjacency.getOrDefault(current, List.of())) {
297	            if (visited.contains(next.toStation())) {
298	                continue;
299	            }
300	            visited.add(next.toStation());
301	            stack.add(next);
302	            dfs(adjacency, next.toStation(), target, visited, stack,
303	                    minutes + next.travelMinutes(), out);
304	            stack.remove(stack.size() - 1);
305	            visited.remove(next.toStation());
306	        }
307	    }
308	
309	    /**
310	     * 由候选路径生成逐段时刻（不中途等待，逐段累加行驶分钟）。
311	     */
312	    private List<RouteLeg> toLegs(long planId, int graphVersion, Path path, Instant depart) {
313	        List<RouteLeg> legs = new ArrayList<>(path.segments().size());
314	        Instant cursor = depart;
315	        for (int i = 0; i < path.segments().size(); i++) {
316	            LineSegment s = path.segments().get(i);
317	            Instant end = cursor.plusSeconds(s.travelMinutes() * 60L);
318	            legs.add(new RouteLeg(planId, graphVersion, i, s.sectionId(), s.fromStation(),
319	                    s.toStation(), s.travelMinutes(), cursor, end));
320	            cursor = end;
321	        }
322	        return legs;
323	    }
324	
325	    /**
326	     * 候选路径各段与已发布计划在同运营日、同区段上的重叠检测（左闭右开，相邻合法）。
327	     */
328	    private boolean hasSectionConflict(LocalDate opDate, List<RouteLeg> legs) {
329	        List<String> sectionIds = legs.stream().map(RouteLeg::sectionId).distinct().toList();
330	        List<PublishedSlot> published = planRepo.findPublishedSlots(opDate, sectionIds, List.of());
331	        for (RouteLeg leg : legs) {
332	            for (PublishedSlot slot : published) {
333	                if (!leg.sectionId().equals(slot.sectionId())) {
334	                    continue;
335	                }
336	                if (leg.startUtc().isBefore(slot.endUtc())
337	                        && slot.startUtc().isBefore(leg.endUtc())) {
338	                    return true;
339	                }
340	            }
341	        }
342	        return false;
343	    }
344	
345	    private RoutePublishResponse toResponse(RoutePublishRequest req, LocalDate opDate,
346	                                            int graphVersion, Path path, List<RouteLeg> legs) {
347	        List<RouteLegView> views = legs.stream()
348	                .map(leg -> new RouteLegView(leg.sectionId(), leg.fromStation(), leg.toStation(),
349	                        leg.travelMinutes(), leg.startUtc(), leg.endUtc()))
350	                .toList();
351	        return new RoutePublishResponse(req.scheduleKey(), opDate, 1, PlanStatus.PUBLISHED.name(),
352	                graphVersion, req.trainNo(), req.fromStation(), req.toStation(), req.departUtc(),
353	                legs.get(legs.size() - 1).endUtc(), path.totalMinutes(), views);
354	    }
355	
356	    /**
357	     * 幂等重放：存在记录且参数一致返回首次结果；参数不一致抛 409。
358	     */
359	    private <T> Optional<T> replayIfPresent(String opType, String requestId, String hash,
360	                                            Class<T> type) {
361	        return idemRepo.find(opType, requestId).map(record -> {
362	            if (!record.requestHash().equals(hash)) {
363	                throw conflict("IDEMPOTENT_KEY_REUSED",
364	                        "requestId 已用于其他参数: " + requestId);
365	            }
366	            return fromJson(record.responseJson(), type);
367	        });
368	    }
369	
370	    /**
371	     * 图替换幂等身份：操作、操作者、期望版本与全部区段参数的结构化序列化，避免分隔符碰撞。
372	     */
373	    private String hashGraphReplace(ReplaceGraphRequest req) {
374	        Map<String, Object> identity = new LinkedHashMap<>();
375	        identity.put("op", OP_GRAPH_REPLACE);
376	        identity.put("operator", req.operator());
377	        identity.put("expectedVersion", req.expectedVersion());
378	        identity.put("segments", req.segments().stream()
379	                .map(s -> {
380	                    Map<String, Object> item = new LinkedHashMap<String, Object>();
381	                    item.put("sectionId", s.sectionId());
382	                    item.put("fromStation", s.fromStation());
383	                    item.put("toStation", s.toStation());
384	                    item.put("travelMinutes", s.travelMinutes());
385	                    return item;
386	                })
387	                .toList());
388	        return sha256(toJson(identity));
389	    }
390	
391	    /**
392	     * 寻径发布幂等身份：操作、操作者、资源与全部参数（含图版本）的结构化序列化。
393	     */
394	    private String hashRoutePublish(RoutePublishRequest req) {
395	        Map<String, Object> identity = new LinkedHashMap<>();
396	        identity.put("op", OP_ROUTE_PUBLISH);
397	        identity.put("operator", req.operator());
398	        identity.put("scheduleKey", req.scheduleKey());
399	        identity.put("graphVersion", req.graphVersion());
400	        identity.put("trainNo", req.trainNo());
401	        identity.put("fromStation", req.fromStation());
402	        identity.put("toStation", req.toStation());
403	        identity.put("departUtc", req.departUtc().toEpochMilli());
404	        identity.put("latestArrivalUtc", req.latestArrivalUtc().toEpochMilli());
405	        return sha256(toJson(identity));
406	    }
407	
408	    private String sha256(String text) {
409	        try {
410	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
411	            byte[] hashed = digest.digest(text.getBytes(StandardCharsets.UTF_8));
412	            StringBuilder hex = new StringBuilder(hashed.length * 2);
413	            for (byte b : hashed) {
414	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
415	                hex.append(Character.forDigit(b & 0xF, 16));
416	            }
417	            return hex.toString();
418	        } catch (NoSuchAlgorithmException e) {
419	            throw new IllegalStateException(e);
420	        }
421	    }
422	
423	    private String toJson(Object value) {
424	        try {
425	            return objectMapper.writeValueAsString(value);
426	        } catch (Exception e) {
427	            throw new IllegalStateException("序列化失败", e);
428	        }
429	    }
430	
431	    private <T> T fromJson(String json, Class<T> type) {
432	        try {
433	            return objectMapper.readValue(json, type);
434	        } catch (Exception e) {
435	            throw new IllegalStateException("幂等响应反序列化失败", e);
436	        }
437	    }
438	
439	    private ApiException badRequest(String message) {
440	        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ARGUMENT", message);
441	    }
442	
443	    private ApiException conflict(String code, String message) {
444	        return new ApiException(HttpStatus.CONFLICT, code, message);
445	    }
446	}
